\u0050\u0025\u003c\u005b\u0050\u004d\u003b\u0055\u002f\u0079\u0026\u0056\u005e\u0037\u0065\u0071\u0051\u0078\u0030\u0031\u0068\u0025\u007a\u0055\u003c\u0054\u002b\u0062\u0069\u0060\u0079\u003c\u0031\u0039\u0077\u006b\u0066\u0065\u0034\u0024\u0078\u0030\u0050\u0051\u007a\u0048\u005d\u0072\u004b\u0022\u003e\u0066\u002b\u003b\u0060\u007a\u0023\u0059\u0045\u0074\u003f\u0050\u007b\u002a\u0029\u002c\u007e\u0073\u002f\u0079\u0026\u0054\u0025\u005e\u0038\u0059\u0060\u0076\u006e\u0046\u005a\u002e\u0056\u0037\u007c\u002a\u0049\u0065\u0032\u0030\u006f\u005e\u0050\u0070\u005f\u0038\u0028\u007d\u005d\u0029\u002f\u007a\u0055\u007b\u0078\u0048\u005e\u0029\u002f\u0026\u0046\u003a\u005d\u007e\u007e\u003b\u0043\u003e\u003f\u0054\u006a\u0023\u0048\u0045\u0079\u0026\u002b\u002f\u0049\u002c\u004b\u006b\u003a\u0071\u0038\u0071\u004b\u003a\u004c\u005d\u004a\u0045\u0034\u0022\u003f\u0034\u0036\u005f\u002c\u0033\u007d\u002a\u007b\u005f\u0040\u0056\u0077\u006e\u004e\u0063\u0025\u003d\u007d\u0070\u0063\u0040\u002e\u006f\u0060\u0021\u003d\u0045\u0075\u0053\u006d\u0048\u0040\u0041\u003c\u006c\u003b\u0037\u0053\u0059\u0052\u0063\u0047\u0064\u004d\u003c\u003a\u002b\u0056\u0063\u005a\u003b\u0045\u002f\u003a\u0063\u006f\u0037\u0030\u006a\u0067\u0045\u006d\u0068\u004d\u0074\u0039\u0038\u006d\u0064\u006e\u0072\u0049\u0034\u0035\u0066\u0029\u0031\u0068\u006f\u0072\u006f\u0057\u0046\u0045\u006c\u0025\u0073\u0040\u0044\u005f\u0075\u0077\u0064\u0048\u006a\u004e\u002c\u0051\u004f\u0024\u006e\u007b\u003e\u007c\u0037\u004e\u003d\u0079\u0039\u003b\u0063\u0068\u0038\u005b\u0048\u002b\u004d\u0030\u003e\u002e\u0067\u0038\u003d\u0026\u006c\u0046\u0031\u004b\u006b\u0050\u0064\u0057\u002e\u0029\u0061\u006a\u0070\u0044\u0058\u0042\u0077\u006d\u0046\u002a\u0064\u0067\u0075\u0039\u0028\u0028\u003c\u0047\u002f\u0025\u0029\u0058\u0066\u002c\u0079\u007e\u0066\u0031\u004b\u006b\u0050\u0073\u0068\u0031\u004b\u0061\u0054\u0074\u002a\u0056\u007c\u0038\u0075\u0072\u003c\u003a\u0074\u0060\u006e\u004d\u004b\u0025\u005b\u0058\u005a\u0078\u003c\u004b\u0051\u0039\u0039\u003a\u002a\u002b\u0056\u0044\u003d\u007b\u004e\u0062\u0065\u0028\u0035\u006f\u0053\u0022\u0044\u0025\u0023\u006d\u0039\u0061\u0022\u003a\u005d\u0036\u0038\u0066\u0041\u006f\u006c\u006d\u0039\u0029\u0046\u004f\u005d\u0045\u0038\u0041\u005a\u0054\u0035\u006e\u0039\u0068\u0055\u0077\u0057\u0071\u005e\u0036\u0034\u0034\u002a\u0075\u004f\u007a\u0066\u006e\u003e\u0022\u0046\u0045\u0025\u003d\u002f\u0049\u007a\u0057\u0041\u0067\u0048\u004e\u003c\u004e\u002c\u0028\u0056\u0065\u0022\u0032\u0061\u0054\u005e\u006d\u003e\u0038\u0073\u007a\u007e\u0036\u0042\u0068\u0051\u0040\u0055\u0047\u0057\u006f\u0053\u0039\u0046\u0052\u005b\u003a\u007a\u0035\u0032\u0053\u0032\u007d\u0062\u0028\u006e\u005f\u006a\u0074\u006a\u0059\u0047\u0040\u0024\u0047\u0043\u0052\u002f\u007d\u0078\u003b\u0079\u0036\u0022\u0040\u0024\u0064\u0053\u0030\u007e\u006a\u0050\u003e\u0072\u0043\u0034\u0075\u006d\u0069\u007c\u004d\u003a\u0070\u0024\u0070\u0041\u002f\u006f\u006c\u002f\u005e\u0023\u006e\u002c\u004b\u0061\u003e\u0039\u0029\u0039\u0075\u0037\u002f\u006f\u004e\u002f\u004c\u0060\u0041\u006e\u0070\u006e\u0032\u0076\u006b\u006c\u007e\u0022\u0050\u0059\u002b\u003f\u002c\u0063\u0048\u002e\u0074\u0061\u0029\u007e\u006c\u0032\u004a\u005a\u004d\u0069\u0072\u0058\u0022\u004d\u0077\u005b\u006f\u005a\u0048\u005f\u006a\u006a\u0079\u0048\u0079\u006b\u0047\u0074\u0073\u006f\u005a\u004d\u007b\u0031\u005b\u006a\u0059\u006b\u0033\u0055\u003f\u007b\u0032\u006a\u004b\u0071\u0079\u0056\u0044\u005f\u005d\u003f\u0061\u0025\u0040\u0062\u0062\u004e\u0026\u0046\u0037\u006a\u0049\u0076\u002f\u0029\u0034\u004d\u005d\u0043\u0025\u004b\u003b\u0035\u006d\u005b\u0047\u005a\u003d\u0024\u002c\u0049\u0056\u002c\u0063\u0057\u0034\u002f\u0069\u0073\u0062\u0023\u005e\u006a\u0070\u0040\u002c\u0048\u0072\u003d\u006b\u0067\u0037\u004e\u0066\u0024\u0043\u0075\u0053\u0028\u004f\u007a\u0037\u003c\u003c\u0022\u0032\u0046\u0058\u0072\u0065\u005b\u003b\u0065\u0043\u0034\u0047\u007e\u003c\u0028\u0021\u0032\u0025\u0032\u0058\u0059\u003d\u0036\u0046\u0074\u003a\u0025\u0072\u0043\u004c\u003a\u0063\u0047\u0055\u0036\u004e\u006d\u004f\u006b\u006f\u0041\u0057\u0074\u0043\u0047\u002b\u006e\u0028\u0026\u007d\u004d\u0037\u0045\u0059\u0028\u0048\u0023\u0079\u0077\u0071\u003d\u0041\u0078\u003a\u0062\u002c\u006a\u0029\u0023\u0070\u0077\u0042\u002c\u0035\u002c\u0046\u0078\u0033\u0047\u0024\u003f\u004b\u0049\u0029\u006c\u0057\u006a\u0052\u0077\u006f\u0040\u0030\u0034\u004a\u004e\u005e\u0046\u0048\u007b\u004b\u0077\u0057\u007b\u006a\u0021\u002e\u0034\u0034\u0039\u0053\u006c\u0034\u004f\u0050\u005a\u0026\u0041\u0031\u0059\u003f\u0030\u006f\u0058\u006f\u006e\u0058\u004d\u006a\u0029\u0034\u0022\u0068\u002b\u0025\u007c\u0035\u0077\u0059\u0050\u005f\u0058\u0037\u0069\u0078\u007c\u003f\u003c\u002e\u0034\u0059\u0058\u004b\u003a\u0053\u007a\u007e\u0045\u0076\u0028\u002b\u005d\u0053\u0033\u0031\u006b\u0061\u006a\u0029\u0077\u007a\u0021\u0063\u0079\u006b\u0026\u0026\u0040\u0072\u007b\u0066\u005b\u0042\u006b\u0063\u007a\u0058\u002c\u007e\u0025\u0046\u0066\u005d\u0028\u002f\u0025\u003a\u005d\u0054\u002c\u004c\u006e\u004e\u0065\u004a\u0028\u004e\u005d\u0062\u0067\u0053\u0028\u0040\u0053\u0059\u006a\u0048\u0041\u0023\u0057\u0024\u004c\u007e\u004b\u004d\u0052\u0032\u006e\u003f\u0023\u006a\u0056\u004d\u003f\u0048\u0079\u0033\u005e\u0042\u0047\u0036\u006d\u0066\u0038\u005f\u0046\u0079\u0065\u0022\u002c\u0057\u003b\u003a\u0077\u007e\u0025\u0038\u0056\u0074\u0066\u0028\u0029\u0024\u007b\u004b\u003e\u0076\u0042\u0026\u0026\u0064\u006a\u0029\u0033\u002a\u0055\u0047\u002a\u0029\u0054\u0032\u0073\u0076\u004f\u0056\u0059\u0022\u002c\u0077\u0071\u0058\u0037\u0074\u0044\u002b\u0029\u0049\u0051\u0077\u0066\u0042\u006f\u0037\u004c\u0069\u0049\u0040\u0063\u0048\u006d\u0039\u0041\u0048\u0051\u0039\u0076\u007e\u0059\u005f\u005f\u0076\u004b\u0041\u003d\u0026\u0030\u0036\u006a\u0056\u004d\u003f\u0048\u0079\u003f\u0071\u002c\u0046\u0041\u0034\u004c\u005d\u0039\u0035\u007d\u0023\u004b\u003e\u0076\u0042\u007d\u0031\u0033\u005e\u0034\u004d\u002b\u0021\u0066\u0049\u007d\u0041\u0041\u0047\u006b\u0076\u0034\u003c\u005f\u005f\u0061\u0042\u007c\u0022\u0047\u002a\u004b\u0068\u003f\u005f\u005d\u0038\u0070\u0061\u0038\u0059\u003d\u0033\u0047\u0063\u005e\u0049\u0022\u0050\u004b\u005d\u0033\u0055\u006e\u0040\u0026\u0035\u0078\u0069\u002c\u0046\u0026\u0073\u0033\u0050\u004c\u0051\u004b\u0034\u0029\u0048\u006c\u0047\u0040\u0050\u0050\u0068\u005f\u0078\u003a\u0033\u007b\u003b\u006e\u0069\u0039\u0028\u007e\u0047\u0074\u003f\u0047\u007a\u0056\u0030\u005d\u0063\u0053\u0050\u0034\u002b\u0068\u0058\u006b\u0069\u005d\u0054\u0030\u003c\u0036\u0064\u0052\u0038\u0053\u0050\u004c\u005e\u0031\u0058\u0066\u004e\u0037\u004a\u0032\u0031\u0054\u007a\u007a\u0050\u0075\u0029\u0036\u0034\u0071\u007e\u0038\u0025\u005b\u0035\u0046\u0070\u0061\u002b\u0067\u0038\u0073\u0053\u0025\u0052\u0049\u0077\u0055\u007d\u0050\u0050\u0068\u005f\u0078\u003a\u0033\u007b\u002e\u007c\u0040\u0051\u0063\u0060\u006d\u0040\u0041\u0073\u003f\u005f\u002c\u004e\u0040\u0025\u007d\u0073\u0053\u0074\u0055\u0043\u0040\u003e\u0033\u0059\u0068\u005f\u0078\u003a\u006b\u004e\u0047\u0024\u005f\u002f\u0050\u0065\u005b\u0028\u003a\u0074\u004e\u0043\u0028\u004d\u0078\u0046\u002c\u0054\u0052\u0032\u0051\u002c\u0065\u0061\u0023\u006d\u0055\u0040\u0046\u0075\u0029\u0036\u003a\u0028\u0047\u0041\u0051\u0029\u002a\u0053\u0021\u0075\u0074\u003e\u003f\u0070\u0051\u0036\u003a\u005a\u0071\u0066\u0069\u003d\u004a\u004c\u0078\u004c\u0068\u0062\u0074\u0064\u005b\u002e\u003c\u0041\u0046\u0063\u004c\u0052\u0022\u0040\u006e\u0032\u0028\u007b\u0049\u003f\u0059\u002e\u0059\u0078\u0024\u0048\u0048\u0064\u005d\u006c\u004b\u0025\u0045\u0071\u0060\u007e\u006c\u006c\u005e\u006b\u0067\u0031\u0058\u0030\u003d\u0064\u0032\u0024\u0048\u0059\u0037\u0070\u0042\u0038\u0036\u003c\u0056\u002f\u0063\u006b\u0029\u0044\u002e\u0022\u0056\u0070\u004a\u0049\u0039\u0059\u0052\u0075\u0021\u0040\u006b\u003e\u0068\u0076\u0036\u002e\u006d\u007a\u0062\u0037\u0070\u0060\u0060\u0037\u003c\u0056\u002f\u0025\u0024\u004d\u0045\u0077\u0056\u0043\u0045\u0058\u006d\u006b\u006e\u003f\u0059\u002e\u0059\u0073\u0024\u004e\u0050\u0061\u003e\u0075\u0030\u005d\u007e\u003c\u0039\u0058\u006d\u0025\u004b\u0056\u004d\u0062\u002e\u0033\u0057\u0060\u003b\u0062\u0077\u0041\u003c\u0045\u0063\u0065\u0043\u0021\u004b\u004c\u0028\u0044\u0051\u0024\u003b\u0040\u0036\u0040\u006f\u0026\u007a\u0062\u0066\u0033\u0023\u0030\u002b\u003d\u007b\u0021\u002a\u0050\u0055\u0042\u0024\u0044\u004c\u0056\u0042\u002c\u007d\u006d\u0074\u003c\u0036\u003a\u0045\u0075\u0049\u006c\u0066\u0074\u0028\u003e\u006e\u0055\u0029\u0061\u0061\u006f\u005e\u003c\u0074\u0063\u006f\u0032\u0028\u0048\u0049\u003f\u0059\u0035\u0059\u0036\u0067\u0048\u0048\u007e\u0036\u0042\u003c\u0074\u0021\u004f\u0043\u0029\u004c\u006a\u0041\u0067\u004d\u0066\u0022\u0030\u006b\u0073\u0079\u0021\u002e\u0056\u0038\u0053\u0063\u003a\u005b\u0065\u006c\u0037\u004e\u007c\u0056\u0032\u0045\u0058\u006d\u0068\u006e\u003f\u0059\u0035\u0059\u0036\u0067\u0048\u0048\u007e\u0036\u0042\u003c\u0074\u0021\u006f\u0044\u0044\u0055\u0045\u006e\u0061\u0029\u0078\u0058\u006d\u0055\u0046\u003f\u0059\u002e\u0059\u0078\u0024\u0048\u0048\u0064\u005d\u0042\u003c\u0046\u004c\u004f\u0043\u006c\u005a\u0058\u006d\u006b\u006e\u003f\u0059\u002e\u0059\u0078\u0024\u0048\u0048\u0064\u005d\u0042\u003c\u0046\u004c\u004f\u0043\u006c\u005a\u0058\u006d\u006b\u006e\u003f\u0059\u002e\u0059\u0078\u0024\u0048\u0048\u0064\u005d\u0042\u003c\u0046\u004c\u004f\u0043\u006c\u005a\u0058\u006d\u006b\u006e\u003f\u0059\u002e\u0059\u0078\u0024\u0048\u0048\u0064\u005d\u0042\u003c\u0046\u004c\u0070\u0061\u002b\u0050\u0058\u006d\u0025\u004b\u005e\u005e\u002a\u003e\u0053\u0022\u005a\u004e\u007e\u0067\u0072\u0040\u0049\u005a\u005f\u004c\u004d\u006e\u004d\u0079\u0052\u0053\u005b\u003f\u0050\u0048\u0022\u0025\u0032\u0073\u003b\u0058\u002c\u004e\u0066\u006d\u0038\u0037\u007a\u0077\u0058\u006d\u0025\u004b\u005e\u005e\u0072\u0042\u004c\u0041\u0048\u0073\u0024\u0064\u004b\u006f\u0066\u0046\u0023\u0052\u0046\u0022\u0028\u0054\u0072\u0053\u0054\u0058\u006d\u005d\u006d\u003f\u0059\u002e\u0059\u0078\u0024\u0048\u0048\u0064\u005d\u0042\u003c\u0046\u004c\u004f\u0043\u006c\u005a\u0058\u006d\u006b\u006e\u003f\u0059\u002e\u0059\u0078\u0024\u0048\u0048\u0064\u005d\u0042\u003c\u0046\u004c\u004f\u0043\u006c\u005a\u0058\u006d\u006b\u006e\u003f\u0059\u002e\u0059\u0078\u0024\u0048\u0048\u0064\u005d\u0042\u003c\u0046\u004c\u004f\u0043\u006c\u005a\u0058\u006d\u006b\u006e\u003f\u0059\u002e\u0059\u0078\u0024\u0048\u0048\u0064\u005d\u0042\u003c\u0046\u004c\u0021\u0044\u004c\u006e\u0042\u0065\u0047\u0030\u0050\u0075\u0029\u004d\u0051\u0043\u006c\u0022\u0066\u0056\u0068\u0050\u0072\u0026\u0033\u0073\u0040\u002b\u0078\u0063\u0045\u0071\u0022\u0052\u002a\u002f\u0037\u0073\u007a\u0073\u007a\u0075\u0045\u006f\u0068\u006b\u0058\u0032\u0047\u0073\u003d\u005f\u0076\u0028\u002f\u004f\u006d\u0060\u0038\u0079\u0042\u0068\u0073\u0028\u0021\u003b\u004e\u0054\u0047\u007b\u004d\u0058\u0077\u0037\u0044\u0056\u0053\u0036\u0056\u0073\u0029\u003c\u0044\u0050\u0041\u002c\u003b\u0037\u003f\u0051\u006c\u0077\u003c\u004a\u0029\u006d\u005d\u005e\u0037\u005d\u0034\u004e\u003d\u004e\u0041\u007c\u0038\u0038\u0058\u0032\u005f\u0046\u0077\u0073\u0025\u0031\u003a\u0037\u004f\u0043\u0077\u0022\u0046\u0054\u0058\u002e\u002c\u0069\u0033\u0069\u0062\u004e\u006f\u0066\u0047\u0028\u0036\u0058\u0053\u004a\u0062\u0072\u007e\u003e\u0037\u0030\u0074\u0041\u0038\u007b\u0043\u0026\u0067\u0074\u0059\u0041\u0044\u003a\u003b\u0037\u007b\u0026\u0028\u0071\u006b\u004b\u007e\u0043\u006e\u007a\u005e\u0048\u0038\u0073\u0036\u0077\u0071\u004a\u007e\u003f\u005e\u007d\u0039\u007d\u0068\u0079\u0026\u0032\u004f\u0073\u0028\u0029\u003c\u0030\u0058\u007b\u006e\u005e\u0037\u0022\u0022\u0074\u0037\u0025\u0038\u004e\u0056\u0046\u0049\u007b\u0045\u002a\u0024\u0068\u0056\u007d\u0036\u0070\u0065\u003c\u006a\u006b\u003b\u002a\u0060\u0037\u0044\u006f\u0046\u0068\u0050\u004f\u006c\u007c\u0051\u0030\u0062\u0053\u0046\u0051\u007c\u006d\u0057\u0062